/// <summary>
/// Finds NDXItemStateTable reocord
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>Record</returns>
static public NDXItemStateTable find(ItemId _itemId, boolean _forUpdate = false)
{
    NDXItemStateTable lNDXItemStateTable;
    KCS_KAoItemStateTable  itemStateTable;
    InventTable lInventTable;
    if(_itemId != '')
    {
        lNDXItemStateTable.selectForUpdate(_forUpdate);

        select firstonly lNDXItemStateTable
            join itemStateTable 
                where itemStateTable.RecId == lNDXItemStateTable.RefRecId_KCS_KAO_ItemStateTable
            join lInventTable
                where lInventTable.KCS_KAOItemState == itemStateTable.ItemState
            && lInventTable.ItemId == _itemId;


    }
    return lNDXItemStateTable;
}

/// <summary>
/// Show inf message for item
/// </summary>
/// <param name = "_itemId">_itemId</param>
public static void ShowInfo(ItemId _itemId)
{
    NDXItemStateTable lNDXItemStateTable = NDXItemStateTable::find(_itemId);
    NDXItemStateTranslation lNDXItemStateTranslation;

    NDXInfoItemState ndxInfoItemState;
    //Info ausgeben
    if(lNDXItemStateTable && lNDXItemStateTable.ShowInfoItemState && lNDXItemStateTable.InfoItemState)
    {
        ndxInfoItemState = lNDXItemStateTable.InfoItemState;

        lNDXItemStateTranslation = NDXItemStateTranslation::find(lNDXItemStateTable.RecId);

        if(lNDXItemStateTranslation)
        {
            ndxInfoItemState = lNDXItemStateTranslation.Description;
        }
        info(strFmt(ndxInfoItemState));
    }

}
